/* Feste Übersetzung der Lerninhalte (fa), maschinell erstellt, nicht von Muttersprachlern geprüft. Code bleibt unverändert. */
(function(r){"use strict";const f=r.SDAkademieFest=r.SDAkademieFest||{};(f["fa"]=f["fa"]||{})["deutsch-b1"]={"Eine Meinung begründen und widersprechen":"دلیل آوردن برای یک نظر و مخالفت کردن","Du vertrittst einen Standpunkt zum Zusammenleben und reagierst respektvoll auf ein Gegenargument.":"دربارهٔ زندگی مشترک یک موقف می‌گیری و به یک دلیل مخالف با احترام جواب می‌دهی.","Weil wie denn verwenden":"weil را مثل denn به کار بردن","Falsch: „Ich bin dafür, weil die Straße ist ruhiger.“ Richtig: „Ich bin dafür, weil die Straße ruhiger ist.“ Das Verb beendet hier die Begründung.":"غلط: „Ich bin dafür, weil die Straße ist ruhiger.“ درست: „Ich bin dafür, weil die Straße ruhiger ist.“ اینجا فعل دلیل را ختم می‌کند.","Teilweise Zustimmung übersehen":"نادیده گرفتن موافقت نسبی","Falsch: „Ich stimme teilweise zu“ als vollständige Ablehnung verstehen. Richtig: Die Person teilt einen Teil der Meinung und hat noch einen Einwand.":"غلط: „Ich stimme teilweise zu“ را رد کامل فهمیدن. درست: شخص با یک قسمت نظر موافق است و هنوز یک اعتراض دارد.","Warum akzeptiert Adil den geänderten Vorschlag?":"چرا Adil پیشنهاد تغییرکرده را قبول می‌کند؟","Weil sonntags alle zu Hause bleiben.":"چون روزهای یکشنبه همه در خانه می‌مانند.","Weil notwendige Fahrten möglich bleiben.":"چون رفت‌وآمدهای ضروری ممکن می‌ماند.","Weil Kinder nicht draußen spielen sollen.":"چون اطفال نباید بیرون بازی کنند.","Die Ausnahme berücksichtigt die Fahrten älterer Menschen; Adil lehnt die Grundidee danach nicht mehr ab.":"این استثنا رفت‌وآمد افراد مسن را در نظر می‌گیرد؛ بعد از آن Adil اصل نظر را دیگر رد نمی‌کند.","Welcher Satz mit denn ist richtig?":"کدام جمله با denn درست است؟","Nach „denn“ bleibt die normale Hauptsatzstellung mit dem Verb an Position zwei erhalten.":"بعد از „denn“ (زیرا) ترتیب عادی جملهٔ اصلی با فعل در جای دوم می‌ماند.","Welche Äußerung enthält einen sachlichen Einwand?":"کدام گفته یک اعتراض واقع‌بینانه دارد؟","Deine Meinung interessiert mich nicht.":"نظر تو برایم مهم نیست.","Wir sollten das auf jeden Fall machen.":"ما باید این کار را حتماً بکنیم.","Allerdings brauchen Anwohner eine Zufahrt.":"اما ساکنان به یک راه ورود نیاز دارند.","Die Zufahrt benennt ein konkretes Problem des Vorschlags, ohne jemanden persönlich anzugreifen.":"راه ورود یک مشکل مشخص پیشنهاد را می‌گوید، بدون اینکه به کسی حملهٔ شخصی شود.","Notiere vor dem Gespräch einen Vorteil und einen Nachteil einer autofreien Straße; entscheide dich anschließend für eine begründete Position.":"پیش از گفت‌وگو یک فایده و یک ضرر سرکِ بدون موتر را یادداشت کن؛ بعد یک موقف با دلیل انتخاب کن.","Über eine autofreie Straße diskutieren":"بحث دربارهٔ یک سرک بدون موتر","Nora: „Ich finde, unsere Straße sollte am Sonntag autofrei sein, weil Kinder dann draußen spielen können.“ Adil: „Den Vorschlag verstehe ich. Allerdings kommen manche ältere Menschen mit dem Auto.“ Nora: „Dann könnten wir eine Ausnahme für ihre Fahrten vorsehen.“ Adil: „Damit wäre ich einverstanden.“ Beide sprechen über dasselbe Problem, gewichten aber unterschiedliche Bedürfnisse. Welche Änderung macht den Vorschlag für Adil akzeptabel?":"Nora: „Ich finde, unsere Straße sollte am Sonntag autofrei sein, weil Kinder dann draußen spielen können.“ Adil: „Den Vorschlag verstehe ich. Allerdings kommen manche ältere Menschen mit dem Auto.“ Nora: „Dann könnten wir eine Ausnahme für ihre Fahrten vorsehen.“ Adil: „Damit wäre ich einverstanden.“ هر دو دربارهٔ یک مشکل گپ می‌زنند، اما به نیازهای مختلف وزن متفاوت می‌دهند. کدام تغییر پیشنهاد را برای Adil قابل قبول می‌سازد؟","Gründe und Einwände verknüpfen":"وصل کردن دلیل‌ها و اعتراض‌ها","„Weil“ eröffnet einen Nebensatz: „Ich bin dafür, weil der Verkehr zu laut ist.“ Das gebeugte Verb schließt diesen Nebensatz ab. „Denn“ verbindet dagegen zwei Hauptsätze: „Ich bin dagegen, denn ich brauche mein Auto.“ Mit „allerdings“ lässt sich ein Einwand ergänzen: „Die Idee ist gut. Allerdings brauchen wir Ausnahmen.“ Hinter dem vorangestellten Adverb folgt unmittelbar das Verb. Formuliere dieselbe Begründung einmal mit „weil“ und einmal mit „denn“.":"„Weil“ یک جملهٔ فرعی را باز می‌کند: „Ich bin dafür, weil der Verkehr zu laut ist.“ فعل صرف‌شده این جملهٔ فرعی را ختم می‌کند. „Denn“ برعکس دو جملهٔ اصلی را وصل می‌کند: „Ich bin dagegen, denn ich brauche mein Auto.“ با „allerdings“ (اما، البته) می‌توان یک اعتراض اضافه کرد: „Die Idee ist gut. Allerdings brauchen wir Ausnahmen.“ بعد از قیدِ اول جمله، فعل فوراً می‌آید. همان دلیل را یک بار با „weil“ و یک بار با „denn“ بنویس.","Standpunkte sprachlich abstufen":"درجه‌بندی موقف‌ها با زبان","Zum Diskutieren gehören die Meinung – die Meinungen, der Vorschlag – die Vorschläge und der Einwand – die Einwände. „Ich bin überzeugt, dass …“ klingt sicherer als „Ich könnte mir vorstellen, dass …“. Mit „Da stimme ich dir teilweise zu“ erkennst du einen Teil des Arguments an. Das bedeutet noch keine vollständige Zustimmung. Wähle eine Formulierung, die deiner tatsächlichen Haltung entspricht, und ergänze einen nachvollziehbaren Grund.":"برای بحث این کلمه‌ها لازم‌اند: die Meinung – die Meinungen (نظر)، der Vorschlag – die Vorschläge (پیشنهاد) و der Einwand – die Einwände (اعتراض). „Ich bin überzeugt, dass …“ (مطمئن هستم که …) مطمئن‌تر از „Ich könnte mir vorstellen, dass …“ (ممکن است که …) به نظر می‌رسد. با „Da stimme ich dir teilweise zu“ یک قسمت دلیل را قبول می‌کنی. این هنوز موافقت کامل نیست. عبارتی را انتخاب کن که با نظر واقعی‌ات مطابق است و یک دلیل قابل فهم اضافه کن.","Auf das Gegenargument eingehen":"جواب دادن به دلیل مخالف","Wiederhole zuerst den Kern des Einwands: „Du möchtest also, dass ältere Menschen weiter fahren können.“ Suche dann eine Lösung, statt nur deine erste Aussage zu wiederholen. „Das ist Unsinn“ bewertet die Person oder ihren Beitrag ab; „Ich sehe das anders, weil …“ erklärt die eigene Sicht. Ein Kompromiss muss beide Anliegen berücksichtigen. Spiele das Gespräch erneut und ersetze den autofreien Sonntag durch einen verkehrsarmen Nachmittag.":"اول اصل اعتراض را تکرار کن: „Du möchtest also, dass ältere Menschen weiter fahren können.“ بعد یک راه‌حل پیدا کن، نه اینکه فقط گفتهٔ اول خود را تکرار کنی. „Das ist Unsinn“ (این بی‌معنا است) شخص یا گفتهٔ او را کوچک می‌سازد؛ „Ich sehe das anders, weil …“ نظر خودت را توضیح می‌دهد. یک مصالحه باید هر دو خواست را در نظر بگیرد. گفت‌وگو را دوباره بازی کن و یکشنبهٔ بدون موتر را با یک بعد از ظهرِ کم‌ترافیک عوض کن.","Begründungen verbinden":"وصل کردن دلیل‌ها","Setze „weil“ und „denn“ jeweils einmal ein.":"„weil“ و „denn“ را هر کدام یک بار بگذار.","Vergleiche die Position von „wird“ und „brauchen“.":"جای „wird“ و „brauchen“ را مقایسه کن.","„Weil“ passt zur Endstellung; „denn“ steht vor dem Hauptsatz mit „brauchen“ an zweiter Stelle.":"„Weil“ با فعل در آخر مناسب است؛ „denn“ پیش از جملهٔ اصلی با „brauchen“ در جای دوم می‌آید.","Gesprächsabsichten unterscheiden":"فرق هدف‌های گفت‌وگو","Verbinde jede Aussage mit ihrer Funktion.":"هر گفته را به کارکرد آن وصل کن.","Achte auf Zustimmung, Problem und mögliche Abhilfe.":"به موافقت، مشکل و راه‌حل ممکن دقت کن.","Die drei Aussagen übernehmen unterschiedliche Aufgaben in derselben Diskussion.":"این سه گفته در یک بحث کارهای مختلف دارند.","Ich bin dafür.":"من موافق هستم.","Allerdings fehlt eine Zufahrt.":"اما راه ورود نیست.","Wir erlauben notwendige Fahrten.":"رفت‌وآمدهای ضروری را اجازه می‌دهیم.","Den Kompromiss erfassen":"فهمیدن مصالحه","Welche Fahrten sollen erlaubt bleiben? Antworte mit einem Wort.":"کدام رفت‌وآمدها اجازه داشته باشند؟ با یک کلمه جواب بده.","Höre auf den Gegensatz zwischen Ausflügen und notwendigen Fahrten.":"به تضاد بین سیل‌ها و رفت‌وآمدهای ضروری گوش بده.","Nora nennt notwendige Fahrten ausdrücklich als Ausnahme.":"Nora رفت‌وآمدهای ضروری را صریح به عنوان استثنا نام می‌برد.","Eine Position mit Einwand schreiben":"نوشتن یک موقف با اعتراض","Schreibe vier Sätze zur autofreien Straße: Meinung, Grund, Gegenargument und Kompromiss.":"چهار جمله دربارهٔ سرک بدون موتر بنویس: نظر، دلیل، دلیل مخالف و مصالحه.","Nutze „allerdings“, um vom Vorteil zum Einwand überzugehen.":"برای رفتن از فایده به اعتراض از „allerdings“ استفاده کن.","Das Beispiel verbindet eine klare Position mit einer begrenzten Ausnahme.":"این مثال یک موقف روشن را با یک استثنای محدود وصل می‌کند.","Enthält deine Meinung einen nachvollziehbaren Grund?":"آیا نظرت یک دلیل قابل فهم دارد؟","Steht das Verb nach „weil“ am Ende?":"آیا فعل بعد از „weil“ در آخر است؟","Gehst du ausdrücklich auf einen Einwand ein?":"آیا صریح به یک اعتراض جواب می‌دهی؟","Berücksichtigt dein Kompromiss beide Seiten?":"آیا مصالحهٔ تو هر دو طرف را در نظر می‌گیرد؟","Ein begründeter Standpunkt nennt ein Argument für die eigene Position.":"یک موقف با دلیل، یک دلیل به نفع نظر خودت می‌گوید.","Ein Kompromiss greift auch das Anliegen der anderen Person auf.":"یک مصالحه خواست طرف مقابل را هم در نظر می‌گیرد.","Höflich nach einem Termin fragen":"مؤدبانه دربارهٔ یک وقت ملاقات پرسیدن","Du bittest eine Behörde schriftlich um einen Ersatztermin und stellst eine präzise Rückfrage.":"از یک اداره کتبی یک وقت ملاقات بدیل می‌خواهی و یک سؤال دقیق می‌پرسی.","Infinitiv nach könnten falsch bilden":"ساختن غلط مصدر بعد از könnten","Falsch: „Könnten Sie den Termin zu verschieben?“ Richtig: „Könnten Sie den Termin verschieben?“ Nach „könnten“ entfällt hier „zu“.":"غلط: „Könnten Sie den Termin zu verschieben?“ درست: „Könnten Sie den Termin verschieben?“ بعد از „könnten“ اینجا „zu“ نمی‌آید.","Bestätigung voraussetzen":"تأیید را از پیش فرض کردن","Falsch: „Mein neuer Termin steht fest“, obwohl nur eine Anfrage versandt wurde. Richtig: „Ich bitte um eine Bestätigung des Ersatztermins.“":"غلط: „Mein neuer Termin steht fest“، در حالی که فقط یک درخواست فرستاده شده است. درست: „Ich bitte um eine Bestätigung des Ersatztermins.“","Welche Bitte ist korrekt und höflich?":"کدام خواهش درست و مؤدبانه است؟","Das Modalverb steht vorn; „anbieten“ schließt die höfliche Frage als Infinitiv ab.":"فعل کمکی در اول است؛ „anbieten“ سؤال مؤدبانه را به شکل مصدر ختم می‌کند.","Welche Rückfrage ist richtig formuliert?":"کدام سؤال درست نوشته شده است؟","Die eingebettete Frage hat einen eigenen Nebensatz mit „brauche“ am Ende.":"سؤالِ درون جمله یک جملهٔ فرعی جدا با „brauche“ در آخر دارد.","Was fehlt bei „Bitte verschieben Sie meinen Termin“?":"در „Bitte verschieben Sie meinen Termin“ چه کم است؟","Eine ausführliche Lebensgeschichte.":"یک قصهٔ مفصل زندگی.","Datum und Uhrzeit des bisherigen Termins.":"تاریخ و ساعت وقت ملاقات قبلی.","Eine bereits erfundene Bestätigungsnummer.":"یک شمارهٔ تأیید ساختگی.","Datum und Uhrzeit ermöglichen die Zuordnung; persönliche Einzelheiten sind dafür nicht erforderlich.":"تاریخ و ساعت شناختن ملاقات را ممکن می‌سازند؛ جزئیات شخصی برای این لازم نیست.","Markiere im Entwurf den bisherigen Termin, deinen Verhinderungsgrund und zwei mögliche Ersatzzeiten.":"در پیش‌نویس، وقت قبلی، دلیل نیامدنت و دو وقت بدیل ممکن را نشانی کن.","Einen Termin telefonisch klären":"روشن کردن یک وقت ملاقات از طریق تیلفون","Mitarbeiterin: „Ihr Termin ist am Dienstag um neun Uhr.“ Farid: „Da muss ich arbeiten. Könnten Sie mir einen Termin am Nachmittag anbieten?“ Mitarbeiterin: „Am Donnerstag um 15 Uhr wäre noch etwas frei.“ Farid: „Das passt. Welche Unterlagen soll ich mitbringen?“ Mitarbeiterin: „Die Liste erhalten Sie mit der Bestätigung.“ Farid trennt die Bitte um Verschiebung von seiner Frage nach den Unterlagen. Er behauptet nicht, bereits eine vollständige Liste zu kennen.":"کارمند: „Ihr Termin ist am Dienstag um neun Uhr.“ Farid: „Da muss ich arbeiten. Könnten Sie mir einen Termin am Nachmittag anbieten?“ کارمند: „Am Donnerstag um 15 Uhr wäre noch etwas frei.“ Farid: „Das passt. Welche Unterlagen soll ich mitbringen?“ کارمند: „Die Liste erhalten Sie mit der Bestätigung.“ Farid خواهش تغییر وقت را از سؤالش دربارهٔ اسناد جدا می‌کند. او ادعا نمی‌کند که از قبل یک فهرست کامل را می‌شناسد.","Mit dem Konjunktiv höflicher bitten":"مؤدبانه‌تر خواهش کردن با Konjunktiv","„Könnten Sie …?“ und „Wäre es möglich, …?“ machen eine Bitte höflicher. „Könnten Sie den Termin verschieben?“ enthält nach dem Modalverb einen Infinitiv ohne „zu“. Dagegen heißt es „Wäre es möglich, den Termin zu verschieben?“. Bei einer indirekten Frage folgt das Verb am Schluss: „Bitte teilen Sie mir mit, welche Unterlagen ich brauche.“ Ein Fragezeichen ist hier nicht nötig, weil der Gesamtsatz als Bitte formuliert ist.":"„Könnten Sie …?“ و „Wäre es möglich, …?“ یک خواهش را مؤدبانه‌تر می‌سازند. „Könnten Sie den Termin verschieben?“ بعد از فعل کمکی یک مصدر بدون „zu“ دارد. برعکس می‌گویند „Wäre es möglich, den Termin zu verschieben?“. در سؤال غیرمستقیم فعل در آخر می‌آید: „Bitte teilen Sie mir mit, welche Unterlagen ich brauche.“ اینجا علامت سؤال لازم نیست، چون کل جمله به شکل خواهش نوشته شده است.","Eine Nachricht übersichtlich aufbauen":"ساختن یک پیام منظم","Der Betreff – die Betreffe nennt knapp das Anliegen, etwa „Bitte um Ersatztermin am 12. Mai“. Nach „Sehr geehrte Frau Bauer,“ beginnt der anschließende Text klein, sofern kein Nomen folgt: „leider kann ich …“. Verwende außerdem die Bestätigung – die Bestätigungen und die Unterlage – die Unterlagen. Trage nur ein Aktenzeichen ein, das dir tatsächlich mitgeteilt wurde. Beende die Nachricht mit „Mit freundlichen Grüßen“ ohne nachfolgendes Komma.":"Der Betreff – die Betreffe (موضوع نامه) خواست را کوتاه می‌گوید، مثلاً „Bitte um Ersatztermin am 12. Mai“. بعد از „Sehr geehrte Frau Bauer,“ متن بعدی با حرف کوچک شروع می‌شود، اگر اسم نیاید: „leider kann ich …“. همچنین die Bestätigung – die Bestätigungen (تأیید) و die Unterlage – die Unterlagen (سند) را به کار ببر. فقط شمارهٔ دوسیه‌ای را بنویس که واقعاً به تو گفته شده است. پیام را با „Mit freundlichen Grüßen“ بدون ویرگول بعد از آن ختم کن.","Ein konkretes Anliegen formulieren":"نوشتن یک خواست مشخص","„Ich brauche einen anderen Termin“ lässt offen, welcher Termin gemeint ist und wann du Zeit hast. Schreibe stattdessen Datum, Uhrzeit und eine kurze Erklärung. Zwei Zeitfenster erleichtern die Antwort. Bitte anschließend um eine Bestätigung; ein eigener Vorschlag ist noch kein gebuchter Termin. Lies deine Nachricht als empfangende Person: Kann sie den alten Termin zuordnen und ohne weitere Nachfrage einen passenden Ersatz prüfen?":"„Ich brauche einen anderen Termin“ روشن نمی‌سازد که کدام وقت منظور است و تو چه وقت فرصت داری. به جای آن تاریخ، ساعت و یک توضیح کوتاه بنویس. دو بازهٔ زمانی جواب را آسان می‌سازد. بعد تأیید بخواه؛ پیشنهاد خودت هنوز یک وقتِ ثبت‌شده نیست. پیامت را مثل گیرنده بخوان: آیا او می‌تواند وقت قبلی را بشناسد و بدون سؤال دیگر یک بدیل مناسب را بررسی کند؟","Eine Bitte vervollständigen":"تکمیل یک خواهش","Ergänze „Könnten“ und „brauche“.":"„Könnten“ و „brauche“ را تکمیل کن.","Das erste Wort eröffnet eine höfliche Frage; das zweite beendet den Nebensatz.":"کلمهٔ اول یک سؤال مؤدبانه را باز می‌کند؛ کلمهٔ دوم جملهٔ فرعی را ختم می‌کند.","Die Bitte verwendet den Konjunktiv, die indirekte Frage die Verbendstellung.":"خواهش Konjunktiv را به کار می‌برد، سؤال غیرمستقیم فعل در آخر را.","Teile einer Behördennachricht":"قسمت‌های یک پیام اداری","Ordne die Textteile ihrer Funktion zu.":"قسمت‌های متن را به کارکرد آن‌ها وصل کن.","Überlege, was vor dem eigentlichen Nachrichtentext steht.":"فکر کن چه چیزی پیش از متن اصلی پیام می‌آید.","Betreff, Anrede und Gruß strukturieren die Nachricht.":"موضوع، خطاب و سلام پایانی پیام را منظم می‌سازند.","Bitte um Ersatztermin":"خواهش برای وقت ملاقات بدیل","Sehr geehrte Frau Bauer,":"خانم Bauer محترم،","Mit freundlichen Grüßen":"با احترام","Die neue Uhrzeit hören":"شنیدن ساعت تازه","Um wie viel Uhr wird ein Termin angeboten? Schreibe die Uhrzeit als Zahl mit Doppelpunkt.":"وقت ملاقات برای چه ساعتی پیشنهاد می‌شود؟ ساعت را به عدد با دو نقطه بنویس.","Unterscheide den bisherigen Termin vom neuen Angebot.":"وقت قبلی را از پیشنهاد تازه جدا کن.","Das Ersatzangebot lautet Donnerstag um 15:00 Uhr.":"پیشنهاد بدیل پنجشنبه ساعت 15:00 است.","Einen Ersatztermin erbitten":"خواستن یک وقت ملاقات بدیل","Schreibe eine Nachricht: Dienstag, 12. Mai, 9 Uhr absagen; Donnerstag oder Freitag nachmittags vorschlagen; nach Unterlagen fragen.":"یک پیام بنویس: سه‌شنبه، 12 می، ساعت 9 را لغو کن؛ پنجشنبه یا جمعه بعد از ظهر را پیشنهاد کن؛ دربارهٔ اسناد بپرس.","Halte den Grund kurz und die möglichen Zeiten eindeutig.":"دلیل را کوتاه و وقت‌های ممکن را روشن بنویس.","Die Musteranfrage enthält alle Angaben, ohne einen neuen Termin als bereits vereinbart darzustellen.":"درخواست نمونه همهٔ معلومات را دارد، بدون اینکه یک وقت تازه را توافق‌شده نشان بدهد.","Ist der bisherige Termin mit Datum und Uhrzeit genannt?":"آیا وقت قبلی با تاریخ و ساعت ذکر شده است؟","Bietest du beide Nachmittage als mögliche Ersatzzeiten an?":"آیا هر دو بعد از ظهر را به عنوان وقت‌های بدیل ممکن پیشنهاد می‌کنی؟","Fragst du mit korrekter Verbendstellung nach den Unterlagen?":"آیا دربارهٔ اسناد با فعل درست در آخر می‌پرسی؟","Bittest du um Bestätigung und verwendest eine passende Anrede?":"آیا تأیید می‌خواهی و خطاب مناسب به کار می‌بری؟","Ein Terminvorschlag wird erst durch die Rückmeldung verbindlich bestätigt.":"یک پیشنهاد وقت تازه با جواب طرف مقابل قطعی تأیید می‌شود.","In der indirekten Frage „welche Unterlagen ich brauche“ folgt „brauche“ zuletzt.":"در سؤال غیرمستقیم „welche Unterlagen ich brauche“ کلمهٔ „brauche“ در آخر می‌آید.","Formulare und Rückfragen verstehen":"فهمیدن فورم‌ها و سؤال‌ها دربارهٔ آن","Du unterscheidest Pflichtangaben und freiwillige Angaben und fragst bei unbekannten Formularfeldern nach.":"معلومات اجباری را از معلومات اختیاری جدا می‌کنی و دربارهٔ خانه‌های ناشناختهٔ فورم سؤال می‌کنی.","Ob und wenn verwechseln":"اشتباه گرفتن ob و wenn","Falsch: „Ich weiß nicht, wenn das Feld freiwillig ist.“ Richtig: „Ich weiß nicht, ob das Feld freiwillig ist.“ Hier geht es um eine offene Ja-Nein-Frage.":"غلط: „Ich weiß nicht, wenn das Feld freiwillig ist.“ درست: „Ich weiß nicht, ob das Feld freiwillig ist.“ اینجا دربارهٔ یک سؤال باز بلی-نخیر است.","Wohnort als ganze Anschrift eintragen":"نوشتن تنها شهر به جای آدرس کامل","Falsch: Im Feld „vollständige Anschrift“ nur „Bonn“ schreiben. Richtig: Straße, Hausnummer, Postleitzahl und Bonn ergänzen.":"غلط: در خانهٔ „vollständige Anschrift“ (آدرس کامل) فقط „Bonn“ نوشتن. درست: سرک، نمبر خانه، کد پستی و Bonn را بنویس.","Welche Frage erkundigt sich nach einer freiwilligen Angabe?":"کدام سؤال دربارهٔ یک معلومات اختیاری می‌پرسد؟","Die Frage mit „ob“ klärt, ob die Angabe erforderlich ist.":"سؤال با „ob“ (آیا) روشن می‌سازد که آیا این معلومات لازم است.","Was bedeutet „gegebenenfalls ausfüllen“?":"„gegebenenfalls ausfüllen“ یعنی چه؟","Das Feld immer mit einer Null ausfüllen.":"خانه را همیشه با صفر پر کردن.","Das Feld in jedem Fall leer lassen.":"خانه را در هر حال خالی گذاشتن.","Das Feld ausfüllen, wenn die genannte Voraussetzung zutrifft.":"خانه را پر کن، اگر شرط گفته‌شده صدق کند.","„Gegebenenfalls“ knüpft die Eintragung an eine passende Bedingung.":"„Gegebenenfalls“ (در صورت لزوم) نوشتن را به یک شرط مناسب وابسته می‌سازد.","Welcher Eintrag ist eine vollständige fiktive Anschrift?":"کدام نوشته یک آدرس خیالیِ کامل است؟","Straße, Hausnummer, Postleitzahl und Ort bilden zusammen die Anschrift.":"سرک، نمبر خانه، کد پستی و شهر با هم آدرس را می‌سازند.","Übe an erfundenen Angaben: Familienname, Vorname und Anschrift. Trage keine echten persönlichen Daten in eine Kursaufgabe ein.":"با معلومات ساختگی تمرین کن: تخلص، نام و آدرس. در تمرین کورس معلومات شخصی واقعی ننویس.","Am Empfang ein Feld erklären lassen":"توضیح خواستن دربارهٔ یک خانه در پذیرش","Elena: „Hier steht Geburtsname. Ist damit mein Vorname gemeint?“ Herr Klein: „Nein, damit ist der Familienname gemeint, den Sie bei Ihrer Geburt hatten.“ Elena: „Mein Familienname hat sich nicht geändert. Soll ich ihn trotzdem eintragen?“ Herr Klein: „Bitte beachten Sie den Hinweis direkt unter dem Feld.“ Elena liest den Hinweis, bevor sie weiterschreibt. Der Dialog zeigt, warum Vermutungen bei unklaren Feldern zu falschen Angaben führen können.":"Elena: „Hier steht Geburtsname. Ist damit mein Vorname gemeint?“ آقای Klein: „Nein, damit ist der Familienname gemeint, den Sie bei Ihrer Geburt hatten.“ Elena: „Mein Familienname hat sich nicht geändert. Soll ich ihn trotzdem eintragen?“ آقای Klein: „Bitte beachten Sie den Hinweis direkt unter dem Feld.“ Elena پیش از ادامهٔ نوشتن، توضیح را می‌خواند. این گفت‌وگو نشان می‌دهد چرا حدس زدن در خانه‌های ناروشن می‌تواند به معلومات غلط برسد.","Indirekte Ja-Nein-Fragen mit ob bilden":"ساختن سؤال‌های غیرمستقیم بلی-نخیر با ob","Eine direkte Frage lautet „Ist die Telefonnummer freiwillig?“. Eingebettet heißt sie „Können Sie mir sagen, ob die Telefonnummer freiwillig ist?“. „Ob“ eröffnet eine Frage, auf die grundsätzlich mit Ja oder Nein geantwortet werden kann. Das Verb rückt hinter die übrigen Satzteile. Eine Frage nach einem konkreten Ort braucht dagegen ein Fragewort: „Wissen Sie, wo ich unterschreiben soll?“ Unterscheide Ungewissheit über eine Tatsache und die Suche nach einer bestimmten Angabe.":"یک سؤال مستقیم این است: „Ist die Telefonnummer freiwillig?“. در درون جمله می‌شود: „Können Sie mir sagen, ob die Telefonnummer freiwillig ist?“. „Ob“ سؤالی را باز می‌کند که اصولاً با بلی یا نخیر جواب داده می‌شود. فعل به بعد از دیگر اجزای جمله می‌رود. اما سؤال دربارهٔ یک جای مشخص به کلمهٔ سؤالی نیاز دارد: „Wissen Sie, wo ich unterschreiben soll?“ تردید دربارهٔ یک واقعیت را از جست‌وجوی یک معلومات مشخص جدا کن.","Angaben im Formular auseinanderhalten":"جدا کردن معلومات در فورم","Die Anschrift – die Anschriften besteht meist aus Straße, Hausnummer, Postleitzahl und Ort. Der Wohnort – die Wohnorte ist nur ein Teil davon. Der Familienname – die Familiennamen und der Vorname – die Vornamen gehören in die jeweils bezeichneten Felder. Ein Sternchen kennzeichnet häufig eine Pflichtangabe; entscheidend ist die Erklärung im jeweiligen Formular. „Gegebenenfalls“ bedeutet, dass eine Angabe nur bei zutreffender Voraussetzung verlangt wird.":"Die Anschrift – die Anschriften (آدرس) اکثراً از سرک، نمبر خانه، کد پستی و شهر ساخته می‌شود. Der Wohnort – die Wohnorte (محل زندگی) فقط یک قسمت آن است. Der Familienname – die Familiennamen (تخلص) و der Vorname – die Vornamen (نام) به خانه‌های مخصوص خود تعلق دارند. یک ستاره اکثراً یک معلومات اجباری را نشان می‌دهد؛ مهم توضیح همان فورم است. „Gegebenenfalls“ یعنی یک معلومات فقط وقتی خواسته می‌شود که شرط آن صدق کند.","Vor dem Abschicken kontrollieren":"بررسی پیش از فرستادن","Vergleiche deine Einträge mit der Aufgabenstellung und den Hinweisen am Feld. Ein leeres freiwilliges Feld ist etwas anderes als eine vergessene Pflichtangabe. Frage bei einer unklaren Abkürzung nach, statt einen Wert zu erfinden. Kontrolliere zuletzt Datumsformat, Empfänger und gegebenenfalls Unterschrift. In dieser Übung reicht eine fiktive Person: So trainierst du das Verstehen, ohne persönliche Nachweise oder echte Zugangsdaten weiterzugeben.":"نوشته‌هایت را با هدایت تمرین و توضیحات کنار خانه مقایسه کن. یک خانهٔ اختیاریِ خالی با یک معلومات اجباریِ فراموش‌شده فرق دارد. دربارهٔ یک مخفف ناروشن بپرس، نه اینکه یک قیمت از خود بسازی. در آخر شکل تاریخ، گیرنده و در صورت لزوم امضا را بررسی کن. در این تمرین یک شخص خیالی کافی است: این طور فهمیدن را تمرین می‌کنی، بدون اینکه اسناد شخصی یا معلومات واقعی ورود را بدهی.","Rückfragen zu Formularfeldern":"سؤال‌ها دربارهٔ خانه‌های فورم","Setze „ob“ und „wo“ passend ein.":"„ob“ و „wo“ را به جای مناسب بگذار.","Nur eine der Fragen lässt sich mit Ja oder Nein beantworten.":"فقط یکی از سؤال‌ها با بلی یا نخیر جواب داده می‌شود.","„Ob“ fragt nach der Pflicht; „wo“ fragt nach dem Ort der Unterschrift.":"„Ob“ دربارهٔ اجباری بودن می‌پرسد؛ „wo“ دربارهٔ جای امضا.","Formularsprache entschlüsseln":"رمزگشایی زبان فورم‌ها","Verbinde jeden Begriff mit seiner Bedeutung.":"هر اصطلاح را به معنای آن وصل کن.","Suche die sinngleiche Alltagsformulierung.":"عبارت روزمرهٔ هم‌معنا را پیدا کن.","Die Zuordnung übersetzt typische Formularwörter in verständliche Begriffe.":"این وصل کردن کلمه‌های معمول فورم را به اصطلاحات قابل فهم ترجمه می‌کند.","Familienname":"تخلص","gegebenenfalls":"در صورت لزوم","Anschrift":"آدرس","Eine Pflichtangabe heraushören":"شنیدن یک معلومات اجباری","Welche Angabe ist freiwillig? Nenne nur das gesuchte Wort.":"کدام معلومات اختیاری است؟ فقط کلمهٔ خواسته‌شده را بگو.","Achte auf das Wort direkt vor „freiwillig“.":"به کلمهٔ درست پیش از „freiwillig“ (اختیاری) دقت کن.","Nur die Telefonnummer wird in diesem Beispiel ausdrücklich als freiwillig bezeichnet.":"در این مثال فقط شمارهٔ تیلفون صریح اختیاری خوانده شده است.","Eine unklare Angabe erfragen":"پرسیدن دربارهٔ یک معلومات ناروشن","Verfasse drei höfliche Fragen: nach dem Geburtsnamen, nach der Pflicht zur Telefonnummer und nach dem Ort der Unterschrift.":"سه سؤال مؤدبانه بنویس: دربارهٔ نام تولد (Geburtsname)، دربارهٔ اجباری بودن شمارهٔ تیلفون و دربارهٔ جای امضا.","Wandle jede direkte Frage erst mündlich in eine indirekte Frage um.":"هر سؤال مستقیم را اول شفاهی به یک سؤال غیرمستقیم تبدیل کن.","Die drei Sätze klären Bedeutung, Verpflichtung und Position der Unterschrift.":"این سه جمله معنا، اجبار و جای امضا را روشن می‌سازند.","Fragst du nach der Bedeutung von „Geburtsname“?":"آیا دربارهٔ معنای „Geburtsname“ می‌پرسی؟","Benutzt du „ob“ für die Frage nach der Pflichtangabe?":"آیا برای سؤال دربارهٔ معلومات اجباری „ob“ به کار می‌بری؟","Fragst du mit „wo“ nach dem Platz der Unterschrift?":"آیا با „wo“ دربارهٔ جای امضا می‌پرسی؟","Enden die eingebetteten Fragen mit dem jeweils gebeugten Verb?":"آیا سؤال‌های درون جمله با فعل صرف‌شده ختم می‌شوند؟","„Ob“ passt zu einer eingebetteten Ja-Nein-Frage.":"„Ob“ با یک سؤال بلی-نخیرِ درون جمله مناسب است.","Lies die Erklärung des Sternchens im konkreten Formular.":"توضیح ستاره را در همان فورم مشخص بخوان.","Menschen und Gegenstände genau beschreiben":"دقیق توصیف کردن اشخاص و اشیا","Du verwendest Relativsätze, um eine Person oder einen verlorenen Gegenstand eindeutig zu bezeichnen.":"جمله‌های موصولی (Relativsätze) را به کار می‌بری تا یک شخص یا یک چیز گم‌شده را روشن مشخص کنی.","Kasus vom Hauptsatz übernehmen":"حالت (Kasus) را از جملهٔ اصلی گرفتن","Falsch: „Der Rucksack, der ich suche, ist grün.“ Richtig: „Der Rucksack, den ich suche, ist grün.“ Im Relativsatz verlangt „suchen“ ein Akkusativobjekt.":"غلط: „Der Rucksack, der ich suche, ist grün.“ درست: „Der Rucksack, den ich suche, ist grün.“ در جملهٔ موصولی „suchen“ یک مفعول Akkusativ می‌خواهد.","Relativsatz ohne Endverb bilden":"ساختن جملهٔ موصولی بدون فعل در آخر","Falsch: „Die Tasche, die hat einen roten Griff, fehlt.“ Richtig: „Die Tasche, die einen roten Griff hat, fehlt.“":"غلط: „Die Tasche, die hat einen roten Griff, fehlt.“ درست: „Die Tasche, die einen roten Griff hat, fehlt.“","Welcher Relativsatz ist korrekt?":"کدام جملهٔ موصولی درست است؟","„Ich suche den Rucksack“ zeigt den benötigten Akkusativ „den“.":"„Ich suche den Rucksack“ حالت Akkusativ لازم „den“ را نشان می‌دهد.","Welche Funktion hat „der“ in „die Frau, der das Heft gehört“?":"„der“ در „die Frau, der das Heft gehört“ چه کارکردی دارد؟","Dativobjekt im Relativsatz.":"مفعول Dativ در جملهٔ موصولی.","Subjekt des Verbs gehört.":"فاعل فعل gehört.","Akkusativobjekt zu Frau.":"مفعول Akkusativ برای Frau.","Das Heft ist das Subjekt; es gehört der Frau, also Dativ.":"Heft فاعل است؛ آن به زن تعلق دارد، پس Dativ.","Welche Beschreibung hilft am besten beim Wiederfinden?":"کدام توصیف برای دوباره پیدا کردن بیشتر کمک می‌کند؟","Farbe und Griff sind überprüfbare Merkmale des gesuchten Gegenstands.":"رنگ و دسته نشانه‌های قابل بررسیِ چیز جست‌وجوشده هستند.","Wähle bei jedem Relativsatz zuerst das Bezugswort und frage dann, welche Aufgabe das Pronomen im Nebensatz erfüllt.":"در هر جملهٔ موصولی اول کلمهٔ مرجع را انتخاب کن و بعد بپرس که ضمیر در جملهٔ فرعی چه کاری دارد.","Im Fundbüro eine Tasche suchen":"در دفتر اشیای پیداشده یک بکس را پالیدن","Mitarbeiter: „Welche Tasche suchen Sie?“ Deniz: „Ich suche den Rucksack, den ich gestern im Bus vergessen habe.“ Mitarbeiter: „Welche Farbe hat er?“ Deniz: „Er ist grün und hat eine Seitentasche, die mit einem Reißverschluss geschlossen wird.“ Mitarbeiter: „Dann beschreiben Sie bitte noch den Inhalt.“ Deniz: „Darin liegt ein Heft, das meinen Namen trägt.“ Die Relativsätze grenzen die Gegenstände genauer ein, ohne für jedes Merkmal einen neuen Hauptsatz anzufangen.":"کارمند: „Welche Tasche suchen Sie?“ Deniz: „Ich suche den Rucksack, den ich gestern im Bus vergessen habe.“ کارمند: „Welche Farbe hat er?“ Deniz: „Er ist grün und hat eine Seitentasche, die mit einem Reißverschluss geschlossen wird.“ کارمند: „Dann beschreiben Sie bitte noch den Inhalt.“ Deniz: „Darin liegt ein Heft, das meinen Namen trägt.“ جمله‌های موصولی اشیا را دقیق‌تر مشخص می‌کنند، بدون اینکه برای هر نشانه یک جملهٔ اصلی تازه شروع شود.","Den Kasus im Relativsatz bestimmen":"تعیین Kasus در جملهٔ موصولی","Das Bezugswort bestimmt Geschlecht und Zahl: „der Rucksack“ ist maskulin, „die Tasche“ feminin. Der Kasus ergibt sich hingegen aus dem Relativsatz. In „der Rucksack, der mir gehört“ ist „der“ das Subjekt. In „der Rucksack, den ich suche“ ist „den“ das Akkusativobjekt zu „suchen“. Das Verb steht hinten. Setze den eingeschobenen Nebensatz zwischen Kommas und lies den Hauptsatz anschließend ohne diesen Zusatz.":"کلمهٔ مرجع جنس و تعداد را تعیین می‌کند: „der Rucksack“ مذکر است، „die Tasche“ مؤنث. اما Kasus از جملهٔ موصولی معلوم می‌شود. در „der Rucksack, der mir gehört“ کلمهٔ „der“ فاعل است. در „der Rucksack, den ich suche“ کلمهٔ „den“ مفعول Akkusativ برای „suchen“ است. فعل در آخر است. جملهٔ فرعیِ میان‌آمده را بین دو ویرگول بگذار و بعد جملهٔ اصلی را بدون این اضافه بخوان.","Merkmale und Beziehungen benennen":"نام بردن نشانه‌ها و رابطه‌ها","Hilfreich sind der Reißverschluss – die Reißverschlüsse, das Fach – die Fächer und der Inhalt – die Inhalte. „Gehören“ verlangt einen Dativ: „die Frau, der das Heft gehört“. Das Relativpronomen „der“ ist hier feminin und Dativ, obwohl es genauso aussieht wie ein maskuliner Artikel. Ersetze den Relativsatz testweise durch „Das Heft gehört der Frau“. So erkennst du die Rolle, statt nur auf die äußere Form zu achten.":"این کلمه‌ها کمک می‌کنند: der Reißverschluss – die Reißverschlüsse (زیپ)، das Fach – die Fächer (خانه، جیب) و der Inhalt – die Inhalte (محتوا). „Gehören“ (تعلق داشتن) Dativ می‌خواهد: „die Frau, der das Heft gehört“. ضمیر موصولی „der“ اینجا مؤنث و Dativ است، با اینکه درست مثل یک حرف تعریف مذکر دیده می‌شود. جملهٔ موصولی را برای آزمایش با „Das Heft gehört der Frau“ عوض کن. این طور نقش را می‌شناسی، نه اینکه فقط به شکل ظاهری نگاه کنی.","Eine Beschreibung eindeutig machen":"روشن ساختن یک توصیف","Nenne Farbe, Größe, auffällige Merkmale und den Verlustort. Der Satz „Ich suche eine Tasche, die schön ist“ grenzt kaum etwas ein. „Ich suche eine schwarze Tasche, die einen roten Griff hat“ hilft deutlich mehr. Bei „die Tasche, die ich im Zug vergessen habe“ muss das Verb trotz der längeren Ortsangabe am Schluss bleiben. Übe eine kurze Fundmeldung und lass eine andere Person den gesuchten Gegenstand aus drei Zeichnungen auswählen.":"رنگ، اندازه، نشانه‌های خاص و جای گم شدن را بگو. جملهٔ „Ich suche eine Tasche, die schön ist“ تقریباً هیچ چیز را مشخص نمی‌کند. „Ich suche eine schwarze Tasche, die einen roten Griff hat“ خیلی بیشتر کمک می‌کند. در „die Tasche, die ich im Zug vergessen habe“ فعل با وجود ذکر طولانی‌تر جای، باید در آخر بماند. یک گزارش کوتاه گم‌شدن را تمرین کن و بگذار یک شخص دیگر چیز جست‌وجوشده را از سه رسم انتخاب کند.","Relativpronomen auswählen":"انتخاب ضمیر موصولی","Ergänze „der“ und „den“ jeweils einmal.":"„der“ و „den“ را هر کدام یک بار تکمیل کن.","Einmal handelt der Mann selbst, einmal wird er gesucht.":"یک بار خود مرد کار می‌کند، یک بار او پالیده می‌شود.","Das Subjekt steht im Nominativ; die gesuchte Person steht im Akkusativ.":"فاعل در Nominativ است؛ شخص جست‌وجوشده در Akkusativ.","Bezüge erkennen":"شناختن رابطه‌ها","Verbinde den Satzanfang mit dem grammatisch passenden Zusatz.":"اول جمله را با اضافهٔ دستوری مناسب وصل کن.","Vergleiche das Geschlecht des Bezugsworts.":"جنس کلمهٔ مرجع را مقایسه کن.","Alle drei Zusätze beschreiben ihr Bezugswort als Subjekt.":"هر سه اضافه کلمهٔ مرجع خود را به عنوان فاعل توصیف می‌کنند.","der Mann":"مرد","die Tasche":"بکس","das Heft":"کتابچه","Das auffällige Merkmal hören":"شنیدن نشانهٔ خاص","Welche Farbe hat der Griff?":"دستهٔ بکس چه رنگ دارد؟","Gesucht ist die Farbe des Griffs, nicht die des Rucksacks.":"رنگ دسته خواسته شده، نه رنگ بکس پشتی.","Deniz beschreibt den Griff ausdrücklich als rot.":"Deniz دسته را صریح سرخ توصیف می‌کند.","Eine Fundmeldung verfassen":"نوشتن یک گزارش گم‌شدن","Beschreibe einen erfundenen verlorenen Rucksack in vier Sätzen. Verwende zwei Relativsätze und nenne einen Verlustort.":"یک بکس پشتی گم‌شدهٔ خیالی را در چهار جمله توصیف کن. دو جملهٔ موصولی به کار ببر و جای گم شدن را بگو.","Prüfe „ich suche den Rucksack“, bevor du das Relativpronomen einsetzt.":"پیش از گذاشتن ضمیر موصولی، „ich suche den Rucksack“ را بررسی کن.","Die Meldung kombiniert erkennbare Merkmale mit einem konkreten Verlustort.":"این گزارش نشانه‌های قابل شناخت را با یک جای مشخص گم شدن وصل می‌کند.","Nennst du Farbe und ein auffälliges Merkmal?":"آیا رنگ و یک نشانهٔ خاص را گفتی؟","Enthält dein Text mindestens zwei Relativsätze?":"آیا متنت دست کم دو جملهٔ موصولی دارد؟","Stimmen Kasus und Geschlecht der Relativpronomen?":"آیا Kasus و جنس ضمیرهای موصولی درست‌اند؟","Stehen Kommas und Endverben an den richtigen Stellen?":"آیا ویرگول‌ها و فعل‌های آخر در جای درست‌اند؟","Der Fall des Relativpronomens wird im Relativsatz bestimmt.":"حالت ضمیر موصولی در جملهٔ موصولی تعیین می‌شود.","Zwei Kommas begrenzen einen eingeschobenen Relativsatz.":"دو ویرگول یک جملهٔ موصولیِ میان‌آمده را محدود می‌کنند.","Ereignisse in zeitlicher Reihenfolge erzählen":"قصه کردن اتفاقات به ترتیب زمانی","Du berichtest über ein Erlebnis und unterscheidest einmalige Ereignisse von wiederholten Situationen.":"از یک تجربه قصه می‌کنی و اتفاقات یک‌باره را از وضعیت‌های تکراری جدا می‌کنی.","Ein einmaliges Gestern mit wenn erzählen":"قصهٔ یک دیروزِ یک‌باره با wenn","Falsch: „Wenn ich gestern ankam, war der Zug weg.“ Richtig: „Als ich gestern ankam, war der Zug weg.“ Gemeint ist ein einzelnes vergangenes Ereignis.":"غلط: „Wenn ich gestern ankam, war der Zug weg.“ درست: „Als ich gestern ankam, war der Zug weg.“ منظور یک اتفاق یک‌بارهٔ گذشته است.","Nach dem Nebensatz das Subjekt vorziehen":"پیش آوردن فاعل بعد از جملهٔ فرعی","Falsch: „Als ich ankam, ich wartete.“ Richtig: „Als ich ankam, wartete ich.“ Der vorangestellte Nebensatz besetzt das Vorfeld.":"غلط: „Als ich ankam, ich wartete.“ درست: „Als ich ankam, wartete ich.“ جملهٔ فرعیِ اول، جای اول را می‌گیرد.","Welches Wort passt zu einem einmaligen Erlebnis gestern?":"کدام کلمه با یک تجربهٔ یک‌باره در دیروز مناسب است؟","„Gestern“ und die einzelne Ankunft sprechen hier für den temporalen Nebensatz mit „als“.":"„Gestern“ و یک رسیدن یک‌باره اینجا جملهٔ فرعی زمانی با „als“ (وقتی که) را می‌خواهند.","Welche Handlung fand während des Wartens statt?":"در وقت انتظار کدام کار انجام شد؟","Mara stieg in den ersten Zug ein.":"Mara به قطار اول سوار شد.","Mara wurde von Luis abgeholt.":"Luis Mara را گرفت.","Mara schrieb ihrer Schwester.":"Mara به خواهرش پیام نوشت.","Im Gespräch sagt Mara, dass sie beim Warten ihrer Schwester schrieb.":"در گفت‌وگو Mara می‌گوید که در وقت انتظار به خواهرش نوشت.","Welcher Satz hat die richtige Wortstellung?":"کدام جمله ترتیب درست کلمه‌ها را دارد؟","Nach dem vollständigen vorangestellten Nebensatz beginnt der Hauptsatz mit „fragte“.":"بعد از جملهٔ فرعیِ کاملِ اول، جملهٔ اصلی با „fragte“ شروع می‌شود.","Zeichne für deine Erzählung drei Stationen: Ausgangslage, unerwartetes Ereignis und Ergebnis.":"برای قصه‌ات سه مرحله رسم کن: وضعیت اول، اتفاق غیرمنتظره و نتیجه.","Von einer verpassten Verbindung berichten":"قصه کردن از یک اتصال از دست‌رفته","Mara: „Als ich gestern am Bahnhof ankam, war mein Zug schon weg.“ Luis: „Was hast du dann gemacht?“ Mara: „Ich habe am Schalter nachgefragt. Während ich wartete, schrieb ich meiner Schwester.“ Luis: „Hat sie dich abgeholt?“ Mara: „Nein, ich habe den nächsten Zug genommen. Wenn ich spät fahre, prüfe ich jetzt immer vorher die Verbindung.“ Mara erzählt zunächst ein einzelnes Erlebnis und beschreibt am Ende eine regelmäßige Gewohnheit.":"Mara: „Als ich gestern am Bahnhof ankam, war mein Zug schon weg.“ Luis: „Was hast du dann gemacht?“ Mara: „Ich habe am Schalter nachgefragt. Während ich wartete, schrieb ich meiner Schwester.“ Luis: „Hat sie dich abgeholt?“ Mara: „Nein, ich habe den nächsten Zug genommen. Wenn ich spät fahre, prüfe ich jetzt immer vorher die Verbindung.“ Mara اول یک تجربهٔ یک‌باره را قصه می‌کند و در آخر یک عادت منظم را توضیح می‌دهد.","Als und wenn sinnvoll unterscheiden":"فرق معقول als و wenn","Für eine einmalige Situation in der Vergangenheit steht häufig „als“: „Als ich gestern ankam, war der Zug weg.“ Bei wiederholten Ereignissen verwendest du „wenn“: „Immer wenn ich spät fuhr, war der Schalter geschlossen.“ „Wenn“ kann außerdem eine zukünftige Bedingung einleiten. Nach beiden Wörtern folgt ein Nebensatz. Beginnt der Gesamtsatz mit diesem Nebensatz, steht im anschließenden Hauptsatz zuerst das gebeugte Verb: „Als ich ankam, wartete Luis bereits.“":"برای یک وضعیت یک‌باره در گذشته اکثراً „als“ می‌آید: „Als ich gestern ankam, war der Zug weg.“ برای اتفاقات تکراری „wenn“ (هر وقت که) به کار می‌بری: „Immer wenn ich spät fuhr, war der Schalter geschlossen.“ „Wenn“ همچنین می‌تواند یک شرط آینده را شروع کند. بعد از هر دو کلمه یک جملهٔ فرعی می‌آید. اگر کل جمله با این جملهٔ فرعی شروع شود، در جملهٔ اصلیِ بعد از آن اول فعل صرف‌شده می‌آید: „Als ich ankam, wartete Luis bereits.“","Gleichzeitigkeit und Ergebnis ausdrücken":"بیان هم‌زمانی و نتیجه","Mit „während“ verbindest du gleichzeitige Handlungen: „Während ich wartete, schrieb ich eine Nachricht.“ „Danach“ zeigt eine spätere Handlung an; es leitet einen Hauptsatz ein. Zum Erlebnis passen die Verbindung – die Verbindungen, der Schalter – die Schalter und die Nachricht – die Nachrichten. Mündlich ist das Perfekt verbreitet; „war“ und „hatte“ sind auch im Gespräch üblich. Vermeide einen unbegründeten Wechsel zwischen Gegenwart und Vergangenheit.":"با „während“ (در حالی که) کارهای هم‌زمان را وصل می‌کنی: „Während ich wartete, schrieb ich eine Nachricht.“ „Danach“ یک کار بعدی را نشان می‌دهد؛ یک جملهٔ اصلی را شروع می‌کند. برای این تجربه این کلمه‌ها مناسب‌اند: die Verbindung – die Verbindungen (اتصال)، der Schalter – die Schalter (کلکین) و die Nachricht – die Nachrichten (پیام). در گفتار Perfekt رایج است؛ „war“ و „hatte“ هم در گپ زدن معمول‌اند. از تغییر بی‌دلیل بین زمان حال و گذشته دوری کن.","Den roten Faden erhalten":"نگه داشتن رشتهٔ قصه","Ein verständlicher Bericht erklärt, wer wann wo war und was dann geschah. Unterscheide Hauptinformationen von Einzelheiten: Die Farbe des Bahnsteigs erklärt den verpassten Zug kaum, die späte Ankunft dagegen schon. „Als ich ankam, ich fragte am Schalter“ enthält einen Stellungsfehler; nach dem vorangestellten Nebensatz folgt „fragte ich“. Erzähle die Szene einer Partnerin und bitte sie, die drei wichtigsten Stationen in der richtigen Reihenfolge zu wiederholen.":"یک گزارش قابل فهم توضیح می‌دهد که کی، چه وقت، کجا بود و بعد چه شد. معلومات اصلی را از جزئیات جدا کن: رنگ پلاتفورم قطارِ از دست‌رفته را توضیح نمی‌دهد، اما دیر رسیدن آن را توضیح می‌دهد. „Als ich ankam, ich fragte am Schalter“ یک اشتباه ترتیب دارد؛ بعد از جملهٔ فرعیِ اول „fragte ich“ می‌آید. صحنه را برای هم‌درست قصه کن و از او بخواه سه مرحلهٔ مهم را به ترتیب درست تکرار کند.","Zeitwörter passend einsetzen":"گذاشتن مناسب کلمه‌های زمانی","Nutze „Als“ für die einzelne Ankunft und „wenn“ für die Gewohnheit.":"„Als“ را برای یک رسیدن یک‌باره و „wenn“ را برای عادت به کار ببر.","Beachte „gestern“ im ersten und „immer“ im zweiten Satz.":"به „gestern“ در جملهٔ اول و „immer“ (همیشه) در جملهٔ دوم دقت کن.","Die Wörter unterscheiden den einmaligen Rückblick von einer wiederkehrenden Situation.":"این کلمه‌ها یادآوری یک‌باره را از یک وضعیت تکراری جدا می‌کنند.","Zeitliche Beziehungen zuordnen":"وصل کردن رابطه‌های زمانی","Verbinde den Ausdruck mit seiner Bedeutung.":"عبارت را به معنای آن وصل کن.","Suche die zeitliche Funktion statt einer Übersetzung Wort für Wort.":"کارکرد زمانی را پیدا کن، نه ترجمهٔ کلمه به کلمه.","Die Ausdrücke ordnen Ereignisse unterschiedlich zueinander.":"این عبارات اتفاقات را به شکل‌های مختلف به هم مرتب می‌کنند.","als ich gestern ankam":"وقتی دیروز رسیدم","immer wenn ich fahre":"هر وقت که سفر می‌کنم","während ich warte":"در حالی که انتظار می‌کشم","Das Ergebnis des Erlebnisses erfassen":"فهمیدن نتیجهٔ تجربه","Welchen Zug nahm Mara am Ende? Antworte mit „den“ und einem Adjektiv sowie „Zug“.":"Mara در آخر کدام قطار را گرفت؟ با „den“، یک صفت و „Zug“ جواب بده.","Höre die Entscheidung nach „deshalb“.":"به تصمیم بعد از „deshalb“ (به همین دلیل) گوش بده.","Mara beendete die Wartezeit mit der nächsten Verbindung.":"Mara وقت انتظار را با اتصال بعدی تمام کرد.","Ein Erlebnis zusammenhängend erzählen":"قصه کردن پیوستهٔ یک تجربه","Schreibe vier bis fünf Sätze über eine verpasste Verbindung. Benutze „als“, „während“ und „danach“.":"چهار تا پنج جمله دربارهٔ یک اتصال از دست‌رفته بنویس. „als“، „während“ و „danach“ را به کار ببر.","Lege erst die Reihenfolge fest und verbinde dann passende Ereignisse.":"اول ترتیب را تعیین کن و بعد اتفاقات مناسب را وصل کن.","Der Bericht führt von der verpassten Verbindung über das Warten zur Ankunft.":"این گزارش از اتصال از دست‌رفته، از طریق انتظار، تا رسیدن می‌رود.","Ist erkennbar, wann und wo das Erlebnis stattfand?":"آیا معلوم است که تجربه چه وقت و کجا اتفاق افتاد؟","Beschreibt „als“ ein einzelnes vergangenes Ereignis?":"آیا „als“ یک اتفاق یک‌بارهٔ گذشته را بیان می‌کند؟","Verbinden die Sätze mit „während“ gleichzeitige Handlungen?":"آیا جمله‌ها با „während“ کارهای هم‌زمان را وصل می‌کنند؟","Bleibt die zeitliche Reihenfolge bis zum Ergebnis verständlich?":"آیا ترتیب زمانی تا نتیجه قابل فهم می‌ماند؟","„Als“ passt zu einem einmaligen Ereignis in der Vergangenheit.":"„Als“ با یک اتفاق یک‌باره در گذشته مناسب است.","„Während“ verbindet hier zwei gleichzeitig ablaufende Tätigkeiten.":"„Während“ اینجا دو کار هم‌زمان را وصل می‌کند.","Eine Beschwerde mit Lösungsvorschlag schreiben":"نوشتن یک شکایت با پیشنهاد راه‌حل","Du schilderst einen Mangel sachlich, beschreibst seine Folgen und bittest um eine konkrete Rückmeldung.":"یک نقص را واقع‌بینانه شرح می‌دهی، نتایج آن را توضیح می‌دهی و یک جواب مشخص می‌خواهی.","Deshalb mit Verbendstellung schreiben":"نوشتن deshalb با فعل در آخر","Falsch: „Deshalb ich den Raum kaum nutzen kann.“ Richtig: „Deshalb kann ich den Raum kaum nutzen.“ „Deshalb“ eröffnet hier einen Hauptsatz.":"غلط: „Deshalb ich den Raum kaum nutzen kann.“ درست: „Deshalb kann ich den Raum kaum nutzen.“ „Deshalb“ اینجا یک جملهٔ اصلی را باز می‌کند.","Beobachtung und Ursache gleichsetzen":"یکی دانستن مشاهده و علت","Falsch: „Der Heizkörper ist kalt, also ist die Pumpe sicher defekt.“ Richtig: „Der Heizkörper bleibt kalt. Bitte lassen Sie die Ursache prüfen.“":"غلط: „Der Heizkörper ist kalt, also ist die Pumpe sicher defekt.“ درست: „Der Heizkörper bleibt kalt. Bitte lassen Sie die Ursache prüfen.“","Welche Aussage beschreibt eine überprüfbare Beobachtung?":"کدام جمله یک مشاهدهٔ قابل بررسی را بیان می‌کند؟","Raum, Zeitraum und kalter Heizkörper lassen sich prüfen; eine Ursache wird nicht erfunden.":"اتاق، مدت و بخاری سرد قابل بررسی‌اند؛ هیچ علتی از خود ساخته نمی‌شود.","Welcher Folgesatz ist grammatisch korrekt?":"کدام جملهٔ نتیجه از نظر دستوری درست است؟","Im Hauptsatz steht nach dem vorangestellten „deshalb“ das Modalverb „kann“.":"در جملهٔ اصلی بعد از „deshalb“ در اول، فعل کمکی „kann“ می‌آید.","Welche Bitte ist für die nächste Rückmeldung konkret?":"کدام خواهش برای جواب بعدی مشخص است؟","Ein Termin zur Überprüfung ist eine klare gewünschte Antwort auf den gemeldeten Mangel.":"یک وقت برای بررسی، یک جواب روشن و خواسته‌شده به نقص گزارش‌شده است.","Prüfe bei deiner Beschwerde getrennt: Was hast du beobachtet, welche Folge hat es und welche Antwort brauchst du?":"در شکایتت جداگانه بررسی کن: چه چیزی دیدی، چه نتیجه‌ای دارد و به چه جوابی نیاز داری؟","Eine Störung in der Wohnung melden":"گزارش یک خرابی در خانه","Anja: „Seit Montag wird die Heizung im Schlafzimmer nicht warm.“ Hausverwaltung: „Sind auch andere Räume betroffen?“ Anja: „Nein, die Küche ist warm. Im Schlafzimmer bleibt der Heizkörper kalt.“ Hausverwaltung: „Wann können wir Sie erreichen?“ Anja: „Heute ab 16 Uhr telefonisch. Bitte teilen Sie mir mit, wann jemand kommen kann.“ Anja beschreibt eine Beobachtung. Sie vermutet weder eine technische Ursache noch behauptet sie einen bereits vereinbarten Reparaturtermin.":"Anja: „Seit Montag wird die Heizung im Schlafzimmer nicht warm.“ مدیریت خانه: „Sind auch andere Räume betroffen?“ Anja: „Nein, die Küche ist warm. Im Schlafzimmer bleibt der Heizkörper kalt.“ مدیریت خانه: „Wann können wir Sie erreichen?“ Anja: „Heute ab 16 Uhr telefonisch. Bitte teilen Sie mir mit, wann jemand kommen kann.“ Anja یک مشاهده را توضیح می‌دهد. او نه یک علت تخنیکی را حدس می‌زند و نه ادعا می‌کند که وقت ترمیم از قبل تعیین شده است.","Mit deshalb die Folge erklären":"توضیح نتیجه با deshalb","„Die Heizung bleibt kalt. Deshalb kann ich den Raum kaum nutzen.“ „Deshalb“ bezieht sich auf einen vorher genannten Grund und steht hier im Vorfeld. Danach folgt „kann“ und anschließend das Subjekt. Vergleiche die Begründung „Ich nutze den Raum kaum, weil er kalt ist“. Die beiden Sätze ordnen denselben Zusammenhang anders: „weil“ führt den Grund ein, „deshalb“ die Folge. Eine klare Beschwerde hält Beobachtung und Folgerung auseinander.":"„Die Heizung bleibt kalt. Deshalb kann ich den Raum kaum nutzen.“ „Deshalb“ به یک دلیلِ قبلاً گفته‌شده اشاره می‌کند و اینجا در جای اول است. بعد از آن „kann“ و سپس فاعل می‌آید. دلیل „Ich nutze den Raum kaum, weil er kalt ist“ را مقایسه کن. این دو جمله یک رابطه را به شکل‌های مختلف مرتب می‌کنند: „weil“ دلیل را می‌آورد، „deshalb“ نتیجه را. یک شکایت روشن مشاهده و نتیجه‌گیری را از هم جدا نگه می‌دارد.","Sachliche Wörter statt pauschaler Vorwürfe":"کلمه‌های واقع‌بینانه به جای ملامتی‌های کلی","Verwende der Mangel – die Mängel, die Störung – die Störungen und die Rückmeldung – die Rückmeldungen. „Der Heizkörper bleibt kalt“ ist genauer als „Ihre Wohnung ist unbrauchbar“. Eine mögliche Bitte lautet „Könnten Sie mir einen Termin zur Überprüfung nennen?“. Notiere Zeitraum, betroffenen Raum und deine Erreichbarkeit. Die Nachricht übt Sprache; eine rechtliche Frist oder einen Anspruch leitest du daraus nicht automatisch ab.":"این کلمه‌ها را به کار ببر: der Mangel – die Mängel (نقص)، die Störung – die Störungen (خرابی) و die Rückmeldung – die Rückmeldungen (جواب). „Der Heizkörper bleibt kalt“ دقیق‌تر از „Ihre Wohnung ist unbrauchbar“ (خانهٔ شما قابل استفاده نیست) است. یک خواهش ممکن این است: „Könnten Sie mir einen Termin zur Überprüfung nennen?“. مدت، اتاق متأثر و وقتی که در دسترس هستی را یادداشت کن. این پیام زبان را تمرین می‌دهد؛ یک مهلت قانونی یا یک حق از آن خودبه‌خود نتیجه نمی‌شود.","Die Nachricht auf Vollständigkeit prüfen":"بررسی کامل بودن پیام","Ein guter Aufbau lautet Betreff, Anrede, Problem, Folge, Bitte und Gruß. Verzichte auf beleidigende Formulierungen und erfundene Ursachen. „Sie haben die Anlage falsch eingebaut“ lässt sich aus einem kalten Heizkörper allein nicht schließen. Wenn du ein Foto erwähnst, muss es tatsächlich vorhanden sein. Bitte um eine konkrete Rückmeldung, etwa einen Terminvorschlag, und kontrolliere vor dem Abschicken, ob deine Kontaktdaten für diesen Zweck nötig und richtig sind.":"یک ساختار خوب این است: موضوع، خطاب، مشکل، نتیجه، خواهش و سلام پایانی. از عبارات توهین‌آمیز و علت‌های ساختگی دوری کن. از یک بخاری سرد به تنهایی نمی‌شود نتیجه گرفت که „Sie haben die Anlage falsch eingebaut“. اگر از یک عکس یاد می‌کنی، باید واقعاً موجود باشد. یک جواب مشخص بخواه، مثلاً یک پیشنهاد وقت، و پیش از فرستادن بررسی کن که آیا معلومات تماس تو برای این هدف لازم و درست است.","Eine Folge grammatisch ergänzen":"تکمیل دستوری یک نتیجه","Ergänze „kann“ und „ist“.":"„kann“ و „ist“ را تکمیل کن.","Vergleiche den Hauptsatz nach „deshalb“ mit dem Nebensatz nach „weil“.":"جملهٔ اصلی بعد از „deshalb“ را با جملهٔ فرعی بعد از „weil“ مقایسه کن.","Das Modalverb folgt auf „deshalb“, während „ist“ den weil-Satz beendet.":"فعل کمکی بعد از „deshalb“ می‌آید، در حالی که „ist“ جملهٔ weil را ختم می‌کند.","Bestandteile der Beschwerde":"قسمت‌های شکایت","Ordne jede Aussage dem passenden Bestandteil zu.":"هر جمله را به قسمت مناسب آن وصل کن.","Trenne den Zustand von seiner Auswirkung und der gewünschten Reaktion.":"وضعیت را از اثر آن و از واکنش خواسته‌شده جدا کن.","Die drei Bestandteile machen Problem und Anliegen nachvollziehbar.":"این سه قسمت مشکل و خواست را قابل فهم می‌سازند.","Die Heizung bleibt kalt.":"بخاری سرد می‌ماند.","Ich kann dort kaum schlafen.":"آنجا به مشکل خواب می‌شوم.","Bitte nennen Sie einen Termin.":"لطفاً یک وقت بگویید.","Die Erreichbarkeit verstehen":"فهمیدن وقت در دسترس بودن","Ab welcher Uhrzeit ist Anja erreichbar? Antworte im Format 16:00.":"Anja از چه ساعتی در دسترس است؟ به شکل 16:00 جواب بده.","Gefragt ist der Beginn der heutigen Erreichbarkeit.":"شروع در دسترس بودنِ امروز خواسته شده است.","Anja bietet heute ab 16:00 Uhr einen telefonischen Kontakt an.":"Anja امروز از ساعت 16:00 تماس تیلفونی را پیشنهاد می‌کند.","Einen Mangel melden":"گزارش دادن یک نقص","Schreibe an die Hausverwaltung: Heizung im Schlafzimmer seit Montag kalt, Küche warm, Bitte um Überprüfung, heute ab 16 Uhr erreichbar.":"به مدیریت خانه بنویس: بخاری اتاق خواب از دوشنبه سرد است، آشپزخانه گرم است، خواهش بررسی، امروز از ساعت 16 در دسترس.","Vermeide eine technische Diagnose und beschreibe stattdessen den Unterschied zwischen den Räumen.":"از تشخیص تخنیکی دوری کن و به جای آن فرق بین اتاق‌ها را توضیح بده.","Die Nachricht liefert gezielte Angaben für eine Rückmeldung.":"این پیام معلومات هدفمند برای یک جواب می‌دهد.","Nennst du Raum und Beginn der Störung?":"آیا اتاق و شروع خرابی را گفتی؟","Trennst du Beobachtung und Vermutung sprachlich?":"آیا مشاهده و حدس را با زبان از هم جدا می‌کنی؟","Enthält deine Nachricht eine konkrete Bitte um Überprüfung?":"آیا پیامت یک خواهش مشخص برای بررسی دارد؟","Ist die heutige Erreichbarkeit eindeutig angegeben?":"آیا در دسترس بودنِ امروز روشن گفته شده است؟","Eine sachliche Beschwerde beschreibt den beobachteten Mangel genau.":"یک شکایت واقع‌بینانه نقص دیده‌شده را دقیق توضیح می‌دهد.","„Deshalb“ nennt eine Folge des zuvor beschriebenen Problems.":"„Deshalb“ یک نتیجهٔ مشکلِ قبلاً گفته‌شده را می‌گوید.","Gemeinsam planen und Aufgaben verteilen":"با هم پلان ساختن و تقسیم وظایف","Du handelst einen gemeinsamen Plan aus, begründest Vorschläge und hältst Zuständigkeiten fest.":"یک پلان مشترک را مذاکره می‌کنی، دلیل پیشنهادها را می‌گویی و مسئولیت‌ها را یادداشت می‌کنی.","Wenn-Satz ohne Inversion anschließen":"وصل کردن جملهٔ wenn بدون جابه‌جایی فعل","Falsch: „Wenn es regnet, wir feiern drinnen.“ Richtig: „Wenn es regnet, feiern wir drinnen.“ Der Hauptsatz beginnt nach dem Nebensatz mit dem Verb.":"غلط: „Wenn es regnet, wir feiern drinnen.“ درست: „Wenn es regnet, feiern wir drinnen.“ جملهٔ اصلی بعد از جملهٔ فرعی با فعل شروع می‌شود.","Vorschlag als erledigte Aufgabe notieren":"یادداشت کردن یک پیشنهاد مثل یک کار انجام‌شده","Falsch: „Der Raum ist reserviert“, nachdem nur „Wir könnten ihn reservieren“ gesagt wurde. Richtig: „Die Reservierung ist vorgeschlagen, aber noch nicht bestätigt.“":"غلط: „Der Raum ist reserviert“، در حالی که فقط „Wir könnten ihn reservieren“ گفته شد. درست: „Die Reservierung ist vorgeschlagen, aber noch nicht bestätigt.“","Welche Aufgabe hat Omar verbindlich übernommen?":"Omar کدام وظیفه را قطعی به عهده گرفته است؟","Die Getränke sofort kaufen.":"نوشیدنی‌ها را فوراً خریدن.","Den Raum heute reservieren.":"اتاق را امروز ریزرف کردن.","Die Einladung bis Freitag schreiben.":"دعوت‌نامه را تا جمعه نوشتن.","Omar sagt ausdrücklich zur Einladung und dem genannten Fertigstellungstermin zu.":"Omar صریح نوشتن دعوت‌نامه و وقتِ گفته‌شده برای تمام کردن آن را قبول می‌کند.","Was bedeutet „bis Freitag“ bei der Einladung?":"„bis Freitag“ در مورد دعوت‌نامه یعنی چه؟","Sie soll ausschließlich am Freitag begonnen werden.":"باید فقط روز جمعه شروع شود.","Sie soll spätestens am Freitag fertig sein.":"باید حد اکثر تا جمعه آماده باشد.","Sie darf erst nach Freitag verschickt werden.":"فقط بعد از جمعه اجازهٔ فرستادن دارد.","„Bis“ setzt hier eine zeitliche Grenze für die Erledigung.":"„Bis“ اینجا یک حد زمانی برای انجام کار می‌گذارد.","Welche Formulierung ist noch ein Vorschlag?":"کدام عبارت هنوز یک پیشنهاد است؟","Der Konjunktiv „könnten“ stellt eine Möglichkeit zur Diskussion; eine Zusage fehlt noch.":"Konjunktiv „könnten“ یک امکان را برای بحث مطرح می‌کند؛ هنوز قول داده نشده است.","Schreibe am Ende eines Planungsgesprächs für jede Aufgabe auf: Wer übernimmt sie und bis wann?":"در آخر یک گفت‌وگوی پلان‌گذاری برای هر وظیفه بنویس: کی آن را به عهده می‌گیرد و تا چه وقت؟","Ein Nachbarschaftsfest organisieren":"سازمان دادن یک جشن همسایه‌ها","Omar: „Wollen wir das Fest im Hof machen?“ Pia: „Gern. Wenn es regnet, brauchen wir aber einen anderen Ort.“ Omar: „Wir könnten den Gemeinschaftsraum reservieren.“ Pia: „Gut. Ich frage heute nach. Kannst du bis Freitag die Einladung schreiben?“ Omar: „Ja. Und wer besorgt die Getränke?“ Pia: „Das klären wir morgen mit dem Team.“ Ein Vorschlag wird durch Zustimmung und eine konkrete Zusage zur Vereinbarung. Die Getränke bleiben dagegen noch eine offene Aufgabe.":"Omar: „Wollen wir das Fest im Hof machen?“ Pia: „Gern. Wenn es regnet, brauchen wir aber einen anderen Ort.“ Omar: „Wir könnten den Gemeinschaftsraum reservieren.“ Pia: „Gut. Ich frage heute nach. Kannst du bis Freitag die Einladung schreiben?“ Omar: „Ja. Und wer besorgt die Getränke?“ Pia: „Das klären wir morgen mit dem Team.“ یک پیشنهاد با موافقت و یک قول مشخص به توافق تبدیل می‌شود. اما نوشیدنی‌ها هنوز یک وظیفهٔ باز می‌مانند.","Bedingungen verständlich ausdrücken":"بیان قابل فهم شرط‌ها","„Wenn es regnet, feiern wir drinnen.“ Der Nebensatz nennt eine Bedingung, der Hauptsatz ihre Folge. Für eine mögliche Alternative eignet sich „Wir könnten …“. Das ist zunächst ein Vorschlag. „Ich reserviere heute den Raum“ ist eine Zusage mit Zuständigkeit und Termin. Verwechsle diese Funktionen nicht: Aus „Jemand könnte einladen“ folgt noch nicht, dass eine bestimmte Person die Einladungen tatsächlich übernimmt.":"„Wenn es regnet, feiern wir drinnen.“ جملهٔ فرعی یک شرط را می‌گوید، جملهٔ اصلی نتیجهٔ آن را. برای یک بدیل ممکن „Wir könnten …“ مناسب است. این اول یک پیشنهاد است. „Ich reserviere heute den Raum“ یک قول با مسئولیت و وقت است. این کارکردها را اشتباه نگیر: از „Jemand könnte einladen“ هنوز نتیجه نمی‌شود که یک شخص مشخص واقعاً دعوت‌ها را به عهده می‌گیرد.","Planungswortschatz aktiv verwenden":"به کار بردن فعالانهٔ لغات پلان‌گذاری","Zum Plan gehören die Aufgabe – die Aufgaben, die Einladung – die Einladungen und die Zusage – die Zusagen. „Übernehmen“ ist ein untrennbares Verb: „Ich übernehme die Einladung.“ „Bis Freitag“ nennt eine späteste Fertigstellung; „am Freitag“ bezeichnet dagegen den Tag einer Handlung. Vergleiche „Ich schicke die Einladung bis Freitag“ und „Das Fest findet am Freitag statt“. Frage bei ungenauen Zeiten nach, wann die Aufgabe spätestens fertig sein soll.":"برای پلان این کلمه‌ها لازم‌اند: die Aufgabe – die Aufgaben (وظیفه)، die Einladung – die Einladungen (دعوت‌نامه) و die Zusage – die Zusagen (قول، قبول). „Übernehmen“ (به عهده گرفتن) یک فعل جدانشدنی است: „Ich übernehme die Einladung.“ „Bis Freitag“ آخرین وقت تمام کردن را می‌گوید؛ „am Freitag“ برعکس روز یک کار را. „Ich schicke die Einladung bis Freitag“ و „Das Fest findet am Freitag statt“ را مقایسه کن. وقتی زمان‌ها ناروشن‌اند، بپرس که وظیفه حد اکثر تا چه وقت باید آماده باشد.","Offene Punkte gemeinsam festhalten":"با هم یادداشت کردن نکته‌های باز","Fasse zum Ende zusammen: „Pia fragt heute nach dem Raum. Omar schreibt bis Freitag die Einladung. Die Getränke besprechen wir morgen.“ Bitte um Korrektur, falls du jemanden falsch verstanden hast. So wird aus einem langen Gespräch eine überschaubare Aufgabenliste. Ein häufiger Fehler ist „Wenn es regnet, wir feiern drinnen“; richtig folgt „feiern wir“. Spiele das Gespräch mit einer zusätzlichen Schwierigkeit, etwa einem noch nicht bestätigten Raum.":"در آخر خلاصه کن: „Pia fragt heute nach dem Raum. Omar schreibt bis Freitag die Einladung. Die Getränke besprechen wir morgen.“ اگر کسی را اشتباه فهمیدی، اصلاح بخواه. این طور از یک گفت‌وگوی طولانی یک فهرست کوتاه وظایف ساخته می‌شود. یک اشتباه معمول „Wenn es regnet, wir feiern drinnen“ است؛ درست „feiern wir“ می‌آید. گفت‌وگو را با یک مشکل اضافی بازی کن، مثلاً اتاقی که هنوز تأیید نشده است.","Einen Plan sprachlich ergänzen":"تکمیل زبانی یک پلان","Setze „feiern“ und „bis“ ein.":"„feiern“ و „bis“ را بگذار.","Nach dem Bedingungssatz folgt das Verb; danach wird eine Frist genannt.":"بعد از جملهٔ شرطی فعل می‌آید؛ بعد از آن یک مهلت گفته می‌شود.","„Feiern“ eröffnet den Hauptsatz, „bis“ markiert die zeitliche Grenze.":"„Feiern“ جملهٔ اصلی را باز می‌کند، „bis“ حد زمانی را نشان می‌دهد.","Plan und Zuständigkeit verbinden":"وصل کردن پلان و مسئولیت","Ordne die Gesprächsangaben zu.":"معلومات گفت‌وگو را وصل کن.","Unterscheide zugesagte Aufgaben und den gemeinsamen offenen Punkt.":"وظایفِ قبول‌شده را از نکتهٔ باز مشترک جدا کن.","Die Zuordnung folgt den ausdrücklich genannten Zuständigkeiten.":"این وصل کردن از مسئولیت‌های صریح گفته‌شده پیروی می‌کند.","Team morgen":"تیم، فردا","Die Frist aus dem Gespräch hören":"شنیدن مهلت از گفت‌وگو","Bis zu welchem Wochentag soll die Einladung fertig sein?":"دعوت‌نامه تا کدام روز هفته باید آماده باشد؟","Die Frist gehört zu Omars Einladung.":"این مهلت مربوط به دعوت‌نامهٔ Omar است.","Der Freitag ist als spätester Termin für die Einladung vereinbart.":"جمعه به عنوان آخرین وقت برای دعوت‌نامه توافق شده است.","Ein Planungsergebnis festhalten":"یادداشت کردن نتیجهٔ پلان‌گذاری","Fasse den Festplan in vier Sätzen zusammen: Regenalternative, Pias Aufgabe, Omars Frist und offener Punkt.":"پلان جشن را در چهار جمله خلاصه کن: بدیل برای باران، وظیفهٔ Pia، مهلت Omar و نکتهٔ باز.","Verwende für unbestätigte Pläne „möchten“ statt „ist reserviert“.":"برای پلان‌های تأییدنشده „möchten“ به جای „ist reserviert“ به کار ببر.","Die Zusammenfassung unterscheidet Absicht, Zusage und offene Entscheidung.":"این خلاصه نیت، قول و تصمیم باز را از هم جدا می‌کند.","Enthält der Plan eine Alternative bei Regen?":"آیا پلان یک بدیل برای باران دارد؟","Sind Pia und Omar mit ihren Aufgaben genannt?":"آیا Pia و Omar با وظایف‌شان ذکر شده‌اند؟","Bleibt die Frist „bis Freitag“ erhalten?":"آیا مهلت „bis Freitag“ حفظ شده است؟","Kennzeichnest du die Getränke als noch offenen Punkt?":"آیا نوشیدنی‌ها را نکتهٔ هنوز باز نشانی می‌کنی؟","Eine Zuständigkeit braucht eine Person, eine Aufgabe und einen Termin.":"یک مسئولیت به یک شخص، یک وظیفه و یک وقت نیاز دارد.","„Bis Freitag“ bezeichnet hier die späteste Fertigstellung.":"„Bis Freitag“ اینجا آخرین وقت تمام کردن را نشان می‌دهد.","B1-Training gezielt vorbereiten":"آمادگی هدفمند برای تمرین B1","Du fasst einen Sachtext zusammen, berichtest über deinen Lernstand und planst die nächsten Übungen für Lesen, Hören, Schreiben und Sprechen.":"یک متن معلوماتی را خلاصه می‌کنی، از سطح یادگیری‌ات خبر می‌دهی و تمرین‌های بعدی را برای خواندن، شنیدن، نوشتن و گپ زدن پلان می‌کنی.","Zusammenfassung um erfundene Angaben erweitern":"افزودن معلومات ساختگی به خلاصه","Falsch: „Der Gesprächskreis kostet zehn Euro“, obwohl der Text „kostenlos“ sagt. Richtig: „Der Gesprächskreis ist kostenlos; eine Anmeldung ist nötig.“":"غلط: „Der Gesprächskreis kostet zehn Euro“، در حالی که متن „kostenlos“ (رایگان) می‌گوید. درست: „Der Gesprächskreis ist kostenlos; eine Anmeldung ist nötig.“","Dass-Satz wie einen Hauptsatz ordnen":"مرتب کردن جملهٔ dass مثل جملهٔ اصلی","Falsch: „Im Text steht, dass der Kurs ist kostenlos.“ Richtig: „Im Text steht, dass der Kurs kostenlos ist.“":"غلط: „Im Text steht, dass der Kurs ist kostenlos.“ درست: „Im Text steht, dass der Kurs kostenlos ist.“","Welche Zusammenfassung entspricht dem Sachtext?":"کدام خلاصه با متن معلوماتی مطابق است؟","Beginn, Kosten und Anmeldepflicht werden ohne Änderung aus dem Text übernommen.":"شروع، هزینه و لزوم ثبت نام بدون تغییر از متن گرفته می‌شوند.","Welcher nächste Schritt passt zu Salmas Hörproblem?":"کدام قدم بعدی با مشکل شنیدن Salma مناسب است؟","Alle Wörter des Lesetextes alphabetisch abschreiben.":"همهٔ کلمه‌های متن خواندن را به ترتیب الفبا نوشتن.","Drei kurze Ansagen hören und die endgültige Uhrzeit notieren.":"سه اعلان کوتاه را شنیدن و ساعت نهایی را یادداشت کردن.","Nur die Anrede eines Briefes auswendig lernen.":"فقط خطاب یک نامه را حفظ کردن.","Die Übung richtet sich unmittelbar auf überhörte Änderungen in Ansagen.":"این تمرین مستقیم به تغییرهای نشنیده‌مانده در اعلان‌ها متوجه است.","Welcher Satz mit dass ist korrekt?":"کدام جمله با dass درست است؟","Im dass-Satz schließt das gebeugte Hilfsverb „hat“ die Verbgruppe ab.":"در جملهٔ dass، فعل کمکی صرف‌شدهٔ „hat“ گروه فعلی را ختم می‌کند.","Wähle nach einer Übungsprüfung genau eine Schwierigkeit aus und übe sie mit einer konkreten Aufgabe, bevor du die gesamte Prüfung wiederholst.":"بعد از یک امتحان تمرینی دقیقاً یک مشکل را انتخاب کن و آن را با یک تمرین مشخص تمرین کن، پیش از اینکه تمام امتحان را تکرار کنی.","Nach einer Übungsprüfung beraten":"مشوره بعد از یک امتحان تمرینی","Lehrerin: „Was hat heute gut geklappt?“ Salma: „Beim Lesen habe ich die Hauptaussagen verstanden. Beim Hören habe ich die geänderte Uhrzeit überhört.“ Lehrerin: „Wie könntest du das üben?“ Salma: „Ich höre kurze Ansagen und notiere nur Änderungen.“ Lehrerin: „Und beim Schreiben?“ Salma: „Ich prüfe zuerst, ob ich alle Punkte der Aufgabe beantwortet habe.“ Salma nennt überprüfbare Beobachtungen statt eines pauschalen Urteils wie „Ich kann gar kein Deutsch“.":"معلم: „Was hat heute gut geklappt?“ Salma: „Beim Lesen habe ich die Hauptaussagen verstanden. Beim Hören habe ich die geänderte Uhrzeit überhört.“ معلم: „Wie könntest du das üben?“ Salma: „Ich höre kurze Ansagen und notiere nur Änderungen.“ معلم: „Und beim Schreiben?“ Salma: „Ich prüfe zuerst, ob ich alle Punkte der Aufgabe beantwortet habe.“ Salma مشاهدات قابل بررسی را می‌گوید، نه یک قضاوت کلی مثل „Ich kann gar kein Deutsch“ (هیچ آلمانی بلد نیستم).","Hauptaussagen knapp wiedergeben":"کوتاه گفتن مطالب اصلی","Ein kurzer Sachtext lautet: „Der Stadtteiltreff bietet ab Juni einen Gesprächskreis an. Er findet dienstags statt. Die Teilnahme ist kostenlos, eine Anmeldung ist jedoch nötig.“ Eine Zusammenfassung nennt Angebot, Zeitpunkt und Voraussetzung, ohne neue Angaben zu erfinden. „Man kann ohne Anmeldung kommen“ wäre ein inhaltlicher Fehler. Mit „Im Text steht, dass …“ leitest du eine Wiedergabe ein; das gebeugte Verb folgt im dass-Satz nach den übrigen Satzgliedern.":"یک متن معلوماتی کوتاه این است: „Der Stadtteiltreff bietet ab Juni einen Gesprächskreis an. Er findet dienstags statt. Die Teilnahme ist kostenlos, eine Anmeldung ist jedoch nötig.“ یک خلاصه، پیشنهاد، وقت و شرط را می‌گوید، بدون اینکه معلومات تازه بسازد. „Man kann ohne Anmeldung kommen“ یک اشتباه محتوایی می‌بود. با „Im Text steht, dass …“ (در متن آمده که …) یک بازگویی را شروع می‌کنی؛ فعل صرف‌شده در جملهٔ dass بعد از دیگر اجزای جمله می‌آید.","Die vier Fertigkeiten getrennt beobachten":"جداگانه مشاهده کردن چهار مهارت","Zur Vorbereitung gehören die Hauptaussage – die Hauptaussagen, die Ansage – die Ansagen und der Lernschritt – die Lernschritte. Beim Lesen suchst du Informationen im Text; beim Hören verfolgst du etwa eine Korrektur der Uhrzeit. Schreiben verlangt passende Inhalte und nachvollziehbaren Aufbau. Sprechen umfasst auch Rückfragen und Reaktionen auf Gesprächspartner. Eine richtige Auswahlfrage beweist noch nicht, dass ein freier Brief oder ein Gespräch sicher gelingt.":"برای آمادگی این کلمه‌ها لازم‌اند: die Hauptaussage – die Hauptaussagen (مطلب اصلی)، die Ansage – die Ansagen (اعلان) و der Lernschritt – die Lernschritte (قدم یادگیری). در خواندن معلومات را در متن می‌پالی؛ در شنیدن مثلاً اصلاح یک ساعت را دنبال می‌کنی. نوشتن محتوای مناسب و ساختار قابل فهم می‌خواهد. گپ زدن سؤال کردن و واکنش به هم‌صحبت را هم در بر می‌گیرد. یک جواب درست در سؤال انتخابی هنوز ثابت نمی‌کند که یک نامهٔ آزاد یا یک گفت‌وگو مطمئن موفق می‌شود.","Vom Kurs zur selbstständigen Übung wechseln":"رفتن از کورس به تمرین مستقل","Nutze anschließend das verlinkte B1-Prüfungstraining im SD Hub. Die Übungsangebote sind eigenständiges Training und keine offizielle Prüfung. Prüfe vor einer echten Anmeldung das konkrete Format des Anbieters. Freie Texte und Gespräche kontrollierst du anhand transparenter Kriterien oder mit einer Lehrperson; ein Kursfortschritt allein ist kein Sprachnachweis. Halte einen kleinen nächsten Schritt fest, etwa „Morgen höre ich drei Ansagen und notiere jeweils die endgültige Uhrzeit“.":"بعد از آن، تمرین امتحان B1 را که در SD Hub لینک شده به کار ببر. این تمرین‌ها آموزش مستقل‌اند و امتحان رسمی نیستند. پیش از ثبت نام واقعی، شکل مشخص امتحانِ ارائه‌دهنده را بررسی کن. متن‌ها و گفت‌وگوهای آزاد را با معیارهای روشن یا با یک معلم بررسی می‌کنی؛ پیشرفت در کورس به تنهایی سند زبان نیست. یک قدم کوچک بعدی را یادداشت کن، مثلاً „Morgen höre ich drei Ansagen und notiere jeweils die endgültige Uhrzeit“.","Eine Hauptaussage wiedergeben":"بازگویی یک مطلب اصلی","Ergänze „dass“ und „ist“.":"„dass“ و „ist“ را تکمیل کن.","Das Bindewort leitet die Wiedergabe ein; „ist“ steht im zweiten Nebensatz am Schluss.":"کلمهٔ وصل‌کننده بازگویی را شروع می‌کند؛ „ist“ در جملهٔ فرعی دوم در آخر است.","„Dass“ eröffnet den Inhaltssatz, dessen konjugiertes Verb hinten steht.":"„Dass“ جملهٔ محتوایی را باز می‌کند که فعل صرف‌شدهٔ آن در آخر است.","Fertigkeiten und Übungen verknüpfen":"وصل کردن مهارت‌ها و تمرین‌ها","Ordne die Aufgabe der vorrangig trainierten Fertigkeit zu.":"هر تمرین را به مهارتی که بیشتر تمرین می‌دهد وصل کن.","Entscheide nach der konkreten Handlung der lernenden Person.":"بر اساس کار مشخص شخصِ یادگیرنده تصمیم بگیر.","Die Aufgaben trainieren jeweils eine andere sprachliche Fertigkeit.":"هر تمرین یک مهارت زبانی دیگر را تمرین می‌دهد.","Informationen im Sachtext finden":"پیدا کردن معلومات در متن معلوماتی","Eine geänderte Uhrzeit in einer Ansage erkennen":"شناختن یک ساعت تغییرکرده در یک اعلان","Auf einen Gesprächsvorschlag reagieren":"واکنش به یک پیشنهاد در گفت‌وگو","Eine korrigierte Uhrzeit erkennen":"شناختن یک ساعت اصلاح‌شده","Wann beginnt das Treffen endgültig? Antworte als Uhrzeit mit Doppelpunkt.":"جلسه در نهایت چه وقت شروع می‌شود؟ به شکل ساعت با دو نقطه جواب بده.","Achte auf die Änderung nach „nun erst“.":"به تغییر بعد از „nun erst“ (حالا تازه) دقت کن.","Die zuerst genannte Zeit wird durch 15:30 Uhr ersetzt.":"وقت اول گفته‌شده با ساعت 15:30 عوض می‌شود.","Einen überprüfbaren Lernplan schreiben":"نوشتن یک پلان یادگیری قابل بررسی","Schreibe vier Sätze: eine Stärke, eine konkrete Schwierigkeit, einen passenden Übungsschritt und eine Art der Selbstkontrolle.":"چهار جمله بنویس: یک نقطهٔ قوت، یک مشکل مشخص، یک قدم تمرینی مناسب و یک راه بررسی خود.","Plane einen kleinen Schritt, den du an einem Tag tatsächlich durchführen kannst.":"یک قدم کوچک پلان کن که واقعاً در یک روز انجام داده بتوانی.","Der Plan verbindet Beobachtung, passende Übung und anschließenden Vergleich.":"این پلان مشاهده، تمرین مناسب و مقایسهٔ بعدی را وصل می‌کند.","Beschreibst du eine Stärke anhand einer Fertigkeit?":"آیا یک نقطهٔ قوت را با یک مهارت توضیح می‌دهی؟","Nennst du eine konkrete statt einer pauschalen Schwierigkeit?":"آیا یک مشکل مشخص می‌گویی، نه یک مشکل کلی؟","Passt der geplante Übungsschritt zu genau dieser Schwierigkeit?":"آیا قدم تمرینیِ پلان‌شده دقیقاً با همین مشکل مناسب است؟","Erklärst du, wie du das Ergebnis anschließend kontrollierst?":"آیا توضیح می‌دهی که نتیجه را بعداً چطور بررسی می‌کنی؟","Eine Zusammenfassung bewahrt die Hauptaussage und erfindet keine Bedingungen.":"یک خلاصه مطلب اصلی را نگه می‌دارد و هیچ شرطی از خود نمی‌سازد.","Ein konkreter Lernschritt lässt sich nach der Übung überprüfen.":"یک قدم مشخص یادگیری بعد از تمرین قابل بررسی است."};})(typeof window!=="undefined"?window:globalThis);
